"""Turn raw EventStreams payloads into flat rows.

Two streams matter:
  * mediawiki.recentchange          -> one row per edit (the thing we score)
  * mediawiki.revision-tags-change  -> fires when `mw-reverted` is added to an
    *existing* revision, i.e. our delayed label.
"""
from __future__ import annotations

import re
import time
from datetime import datetime

EDIT_STREAM = "mediawiki.recentchange"
TAGS_STREAM = "mediawiki.revision-tags-change"

_IPV4 = re.compile(r"^\d{1,3}(\.\d{1,3}){3}$")
_IPV6 = re.compile(r"^[0-9A-Fa-f:]+:[0-9A-Fa-f:]*$")

# Revert edit summaries generated by MediaWiki / Twinkle / rollback.
_REVERT_COMMENT = re.compile(
    r"(?:Undid revision \d+ by|Reverted (?:\d+ )?edits? by|Reverting edit\(s\) by|"
    r"Restored revision \d+ by|\brv[vs]?\b|\brevert)",
    re.IGNORECASE,
)
_REVERTED_USER = re.compile(
    r"(?:Undid revision \d+ by|Reverted (?:\d+ )?edits? by|Reverting edit\(s\) by)\s*"
    r"\[\[(?:Special:Contrib(?:utions)?/|User:)([^|\]]+)",
    re.IGNORECASE,
)


# Semi-automated batch tools run from ordinary (non-bot) accounts. Thousands of
# near-identical edits per hour; not something a vandalism queue should score.
_BATCH_TOOL = re.compile(r"(quickcategories|\[\[(?:WP|Wikipedia):(?:AWB|JWB)|using AWB|"
                         r"Cat-a-lot|\[\[(?:WP|Wikipedia):Mass|PetScan|Pywikibot)", re.IGNORECASE)


def is_batch_tool(comment: str) -> bool:
    return bool(_BATCH_TOOL.search(comment or ""))


def parse_ts(iso: str) -> float:
    return datetime.fromisoformat(iso.replace("Z", "+00:00")).timestamp()


def normalize_title(title: str) -> str:
    return title.replace("_", " ")


def is_anonymous(user: str) -> bool:
    """IP editors, plus temporary accounts ("~2026-12345-67") that replaced them."""
    return user.startswith("~") or bool(_IPV4.match(user)) or bool(_IPV6.match(user))


def is_revert_comment(comment: str) -> bool:
    return bool(_REVERT_COMMENT.search(comment or ""))


def reverted_user_from_comment(comment: str) -> str | None:
    m = _REVERTED_USER.search(comment or "")
    return m.group(1).strip() if m else None


def edit_row(ev: dict) -> dict | None:
    """recentchange event -> edit row. Schema matches the existing data/raw files."""
    if ev.get("type") != "edit":
        return None
    rev = ev.get("revision") or {}
    length = ev.get("length") or {}
    if not rev.get("new"):
        return None
    return {
        "event_id": f"{ev['wiki']}_{rev['new']}",
        "timestamp": int(ev["timestamp"]),
        "user": ev.get("user", ""),
        "bot": bool(ev.get("bot", False)),
        "minor": bool(ev.get("minor", False)),
        "title": ev.get("title", ""),
        "namespace": int(ev.get("namespace", 0)),
        "comment": ev.get("comment", "") or "",
        "revision_new": int(rev["new"]),
        "revision_old": int(rev.get("old") or 0),
        "length_new": int(length.get("new") or 0),
        "length_old": int(length.get("old") or 0),
        "wiki": ev["wiki"],
        "ingestion_ts": time.time(),
    }


def revert_row(ev: dict) -> dict | None:
    """revision-tags-change event -> revert row, only if `mw-reverted` was just added."""
    added = set(ev.get("tags") or []) - set((ev.get("prior_state") or {}).get("tags") or [])
    if "mw-reverted" not in added:
        return None
    return {
        "wiki": ev["database"],
        "rev_id": int(ev["rev_id"]),
        "title": normalize_title(ev.get("page_title", "")),
        "namespace": int(ev.get("page_namespace", 0)),
        "rev_ts": parse_ts(ev["rev_timestamp"]),
        "revert_ts": parse_ts(ev["meta"]["dt"]),
        "ingestion_ts": time.time(),
    }
